local ChessCarver = {}
local PRODUCTS = {
    chess_pawn = { name = "Kmet", woodCost = 1, time = 1, cost = 5, description = "Šahovska figura kmet." },
    chess_knight = { name = "Skakač", woodCost = 1, boneCost = 1, time = 3, cost = 20, description = "Skakač iz lesa in kosti." },
    chess_set = { name = "Šahovska garnitura", woodCost = 10, boneCost = 5, time = 20, cost = 200, happiness = 8, prestige = 5, knowledge = 5, description = "Celotna garnitura 32 figur." },
    chess_board = { name = "Šahovska deska", woodCost = 8, paintCost = 1, time = 10, cost = 80, happiness = 3, description = "Inlaid šahovska deska." },
    ivory_set = { name = "Slonokoščena garnitura", ivoryCost = 5, time = 40, cost = 800, happiness = 12, prestige = 20, knowledge = 8, description = "Luksuzna garnitura iz slonovine." },
    royal_chess = { name = "Kraljevski šah", ivoryCost = 5, goldCost = 2, jewelCost = 1, woodCost = 5, time = 60, cost = 2000, happiness = 20, prestige = 40, knowledge = 15, description = "Zlati in dragoceni šah za kralja." },
}
local BUILDINGS = {
    workshop = { name = "Šahovska delavnica", cost = { gold = 200, wood = 100 }, upkeep = 5, qualityBonus = 5 },
    carving_studio = { name = "Rezbarski atelje", cost = { gold = 800, wood = 200, stone = 200 }, upkeep = 20, qualityBonus = 15 },
    inlay_workshop = { name = "Intarzijska delavnica", cost = { gold = 1500, wood = 300, stone = 300, iron = 30 }, upkeep = 30, qualityBonus = 25, prestigeBonus = 5 },
    royal_carver = { name = "Kraljevski rezbar", cost = { gold = 4000, wood = 400, stone = 600, gold = 30 }, upkeep = 80, qualityBonus = 40, prestigeBonus = 20 },
}
ChessCarver.woodStock = 15; ChessCarver.boneStock = 5; ChessCarver.ivoryStock = 3; ChessCarver.paintStock = 3; ChessCarver.goldStock = 2; ChessCarver.jewelStock = 2
ChessCarver.productStock = {}; ChessCarver.buildings = {}; ChessCarver.carver = nil; ChessCarver.activeMaking = {}; ChessCarver.totalProducts = 0; ChessCarver.dayTimer = 0
function ChessCarver.init() ChessCarver.woodStock=15; ChessCarver.boneStock=5; ChessCarver.ivoryStock=3; ChessCarver.paintStock=3; ChessCarver.goldStock=2; ChessCarver.jewelStock=2; ChessCarver.productStock={}; ChessCarver.buildings={}; ChessCarver.carver=nil; ChessCarver.activeMaking={}; ChessCarver.totalProducts=0; ChessCarver.dayTimer=0; print("[ChessCarver] Royal Chess Piece & Board Game Carver System initialized (6 products, 4 buildings)") end
function ChessCarver.hireCarver(n,s) s=s or math.random(40,85); local c=350+s*7; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ChessCarver.carver={name=n or ("Rezbar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rezbar najet: %s (spretnost: %d)",ChessCarver.carver.name,s),"success") end; return true end
function ChessCarver.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ChessCarver.build(id) local ok,e=ChessCarver.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ChessCarver.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ChessCarver.getQualityBonus() local b=0; for _,bd in ipairs(ChessCarver.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ChessCarver.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and ChessCarver.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.boneCost and ChessCarver.boneStock<(d.boneCost or 0) then return false,"Premalo kosti" end; if d.ivoryCost and ChessCarver.ivoryStock<(d.ivoryCost or 0) then return false,"Premalo slonovine" end; if d.paintCost and ChessCarver.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.goldCost and ChessCarver.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ChessCarver.jewelStock<(d.jewelCost or 0) then return false,"Premalo dragih kamnov" end; if #ChessCarver.buildings==0 then return false,"Potrebna delavnica" end; if not ChessCarver.carver then return false,"Potreben rezbar" end; return true end
function ChessCarver.make(pt) local ok,e=ChessCarver.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then ChessCarver.woodStock=ChessCarver.woodStock-d.woodCost end; if d.boneCost then ChessCarver.boneStock=ChessCarver.boneStock-d.boneCost end; if d.ivoryCost then ChessCarver.ivoryStock=ChessCarver.ivoryStock-d.ivoryCost end; if d.paintCost then ChessCarver.paintStock=ChessCarver.paintStock-d.paintCost end; if d.goldCost then ChessCarver.goldStock=ChessCarver.goldStock-d.goldCost end; if d.jewelCost then ChessCarver.jewelStock=ChessCarver.jewelStock-d.jewelCost end; local t=d.time; if ChessCarver.carver then t=math.max(1,t-math.floor(ChessCarver.carver.skill/10)) end; table.insert(ChessCarver.activeMaking,{id="chess_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost,happiness=d.happiness or 0,prestige=d.prestige or 0,knowledge=d.knowledge or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rezbarjenje: %s (%d dni)",d.name,t),"info") end; return true end
function ChessCarver.completeMaking(m) local q=1.0+(ChessCarver.getQualityBonus()/100); if ChessCarver.carver then q=q+(ChessCarver.carver.skill/200) end; q=math.min(2.5,q); ChessCarver.productStock[m.productType]=(ChessCarver.productStock[m.productType] or 0)+1; ChessCarver.totalProducts=ChessCarver.totalProducts+1; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness*q) end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.knowledge>0 and _G.Culture then pcall(function() _G.Culture.knowledgePoints=(_G.Culture.knowledgePoints or 0)+m.knowledge end) end; if ChessCarver.carver then ChessCarver.carver.itemsMade=ChessCarver.carver.itemsMade+1; if math.random()<0.15 then ChessCarver.carver.skill=math.min(100,ChessCarver.carver.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Šah izrezljan: %s (kakovost: %.1f)",m.productName,q),"success") end end
function ChessCarver.update(dt) if not _G.state then return end; ChessCarver.dayTimer=ChessCarver.dayTimer+dt; if ChessCarver.dayTimer>=30 then ChessCarver.dayTimer=0; for i=#ChessCarver.activeMaking,1,-1 do local m=ChessCarver.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ChessCarver.completeMaking(m); table.remove(ChessCarver.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ChessCarver.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ChessCarver.carver then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ChessCarver.getStats() return {woodStock=ChessCarver.woodStock,ivoryStock=ChessCarver.ivoryStock,productStock=ChessCarver.productStock,numBuildings=#ChessCarver.buildings,hasCarver=ChessCarver.carver~=nil,carverName=ChessCarver.carver and ChessCarver.carver.name or "—",carverSkill=ChessCarver.carver and ChessCarver.carver.skill or 0,activeMaking=#ChessCarver.activeMaking,totalProducts=ChessCarver.totalProducts} end
return ChessCarver
